30	import io.opentelemetry.api.OpenTelemetry;
31	import io.opentelemetry.context.Context;
32	import io.opentelemetry.context.propagation.TextMapGetter;
33	import io.opentelemetry.context.propagation.TextMapPropagator;
34	import io.opentelemetry.context.propagation.TextMapSetter;
35	
36	class OpenTelemetryTracer implements Tracer {
37	    private static final TextMapGetter GETTER = new Getter();
38	    private static final TextMapSetter SETTER = new Setter();
39	    private final OpenTelemetry telemetry;
40	    private final io.opentelemetry.api.trace.Tracer delegate;
41	    private final boolean enabled;
42	    private final TextMapPropagator propagator;
43	    private final Map<String, String> tags;
44	
45	    OpenTelemetryTracer(OpenTelemetry telemetry, io.opentelemetry.api.trace.Tracer tracer, Map<String, String> tags) {
46	        this.telemetry = telemetry;
47	        this.delegate = tracer;
48	        this.enabled = !tracer.getClass().getSimpleName().equals("DefaultTracer");
49	        this.propagator = telemetry.getPropagators().getTextMapPropagator();
50	        this.tags = tags;
51	    }
52	
53	    static Builder builder() {
54	        return new Builder();
55	    }
56	
57	    @Override
58	    public boolean enabled() {
59	        return enabled;
60	    }
61	
62	    @Override
63	    public Span.Builder<?> spanBuilder(String name) {
64	        OpenTelemetrySpanBuilder builder = new OpenTelemetrySpanBuilder(delegate.spanBuilder(name));
65	        tags.forEach(builder::tag);
66	        return builder;
67	    }
68	
69	    @Override
70	    public Optional<SpanContext> extract(HeaderProvider headersProvider) {
71	        Context context = propagator.extract(Context.current(), headersProvider, GETTER);
72	
73	        return Optional.ofNullable(context)
74	                .map(OpenTelemetrySpanContext::new);
75	    }
76	
77	    @Override
78	    public void inject(SpanContext spanContext, HeaderProvider inboundHeadersProvider, HeaderConsumer outboundHeadersConsumer) {
79	        propagator.inject(((OpenTelemetrySpanContext) spanContext).openTelemetry(), outboundHeadersConsumer, SETTER);
80	    }
81	
82	    @Override
83	    public <T> T unwrap(Class<T> tracerClass) {
84	        if (tracerClass.isAssignableFrom(delegate.getClass())) {
85	            return tracerClass.cast(delegate);
86	        }
87	        throw new IllegalArgumentException("Cannot provide an instance of " + tracerClass.getName()
88	                                                   + ", telemetry tracer is: " + delegate.getClass().getName());
89	    }
90	
91	    static class Builder implements TracerBuilder<Builder> {
92	        private OpenTelemetry ot;
93	        private String serviceName = "helidon-service";
94	        private boolean registerGlobal;
95	
96	        @Override
97	        public Tracer build() {
98	            if (ot == null) {
99	                ot = GlobalOpenTelemetry.get();
100	            }
101	            io.opentelemetry.api.trace.Tracer tracer = ot.getTracer(serviceName);
102	            Tracer result = new OpenTelemetryTracer(ot, tracer, Map.of());
103	            if (registerGlobal) {
104	                Tracer.global(result);
105	            }
106	            return result;
107	        }
108	
109	        Builder openTelemetry(OpenTelemetry ot) {
110	            this.ot = ot;
111	            return this;
112	        }
113	
114	        @Override
115	        public Builder serviceName(String name) {
116	            this.serviceName = name;
117	            return this;
118	        }
119	
120	        @Override
121	        public Builder collectorProtocol(String protocol) {
122	            return this;
123	        }
124	
125	        @Override
126	        public Builder collectorPort(int port) {
127	            return this;
128	        }
129	
130	        @Override
131	        public Builder collectorHost(String host) {
132	            return this;
133	        }
134	
135	        @Override
136	        public Builder collectorPath(String path) {
137	            return this;
138	        }
139	
140	        @Override
141	        public Builder addTracerTag(String key, String value) {
142	            return this;
143	        }
144	
145	        @Override
146	        public Builder addTracerTag(String key, Number value) {
147	            return this;
148	        }
149	
150	        @Override
151	        public Builder addTracerTag(String key, boolean value) {
152	            return this;
153	        }
154	
155	        @Override
156	        public Builder config(Config config) {
157	            return this;
158	        }
159	
160	        @Override
161	        public Builder enabled(boolean enabled) {
162	            return this;
163	        }
164	
165	        @Override
166	        public Builder registerGlobal(boolean global) {
167	            this.registerGlobal = global;
168	            return this;
169	        }
170	
171	        @Override
172	        public <B> B unwrap(Class<B> builderClass) {
173	            if (builderClass.isAssignableFrom(getClass())) {
174	                return builderClass.cast(this);
175	            }
176	            throw new IllegalArgumentException("Cannot unwrap " + builderClass + " from Opentelmetry tracer builder.");
177	        }
178	    }
179	
180	    private static class Getter implements TextMapGetter<HeaderProvider> {
181	        @Override
182	        public Iterable<String> keys(HeaderProvider headerProvider) {
183	            return headerProvider.keys();
184	        }
185	
186	        @Override
187	        public String get(HeaderProvider headerProvider, String s) {
188	            return headerProvider.get(s).orElse(null);
189	        }
190	    }
191	
192	    private static class Setter implements TextMapSetter<HeaderConsumer> {
193	        @Override
194	        public void set(HeaderConsumer carrier, String key, String value) {
195	            carrier.set(key, value);
196	        }
197	    }
