16	package io.helidon.tracing;
17	
18	import java.util.List;
19	import java.util.Optional;
20	import java.util.ServiceLoader;
21	
22	import io.helidon.common.serviceloader.HelidonServiceLoader;
23	import io.helidon.tracing.spi.TracerProvider;
24	
25	/**
26	 * Tracer provider helper to find implementation to use.
27	 */
28	final class TracerProviderHelper {
29	    private static final System.Logger LOGGER = System.getLogger(TracerProviderHelper.class.getName());
30	    private static final TracerProvider TRACER_PROVIDER;
31	
32	    static {
33	        TracerProvider provider = null;
34	        try {
35	            List<TracerProvider> allProviders = HelidonServiceLoader.builder(ServiceLoader.load(TracerProvider.class))
36	                    .addService(new NoOpTracerProvider(), 100000)
37	                    .build()
38	                    .asList();
39	
40	            if (allProviders.size() == 1 || allProviders.size() == 2) {
41	                // only noop or one and noop
42	                provider = allProviders.get(0);
43	            }
44	            for (TracerProvider aProvider : allProviders) {
45	                if (aProvider.available()) {
46	                    provider = aProvider;
47	                    break;
48	                }
49	            }
50	        } catch (Throwable e) {
51	            LOGGER.log(System.Logger.Level.WARNING, "Failed to set up tracer provider, using no-op", e);
52	        }
53	
54	        TRACER_PROVIDER = provider == null ? new NoOpTracerProvider() : provider;
55	    }
56	
57	    private TracerProviderHelper() {
58	    }
59	
60	    public static Optional<Span> currentSpan() {
61	        return TRACER_PROVIDER.currentSpan();
62	    }
63	
64	    static Tracer global() {
65	        return TRACER_PROVIDER.global();
66	    }
67	
68	    static void global(Tracer tracer) {
69	        TRACER_PROVIDER.global(tracer);
70	    }
71	
72	    static TracerBuilder<?> findTracerBuilder() {
73	        return TRACER_PROVIDER.createBuilder();
74	    }
75	}
