package io.helidon.tracing.opentelemetry;

import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BiConsumer;

import io.opentelemetry.api.baggage.Baggage;
import io.opentelemetry.api.baggage.BaggageBuilder;
import io.opentelemetry.api.baggage.BaggageEntry;
import io.opentelemetry.api.baggage.BaggageEntryMetadata;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.Scope;

/**
 * Mutable implementation of OpenTelemetry {@link io.opentelemetry.api.baggage.Baggage} which is bound to a single span.
 * <p>
 * Baggage entries can be added or updated at any time without touching the OpenTelemetry {@link io.opentelemetry.context.Context}.
 * The baggage is only made current (added to the context) when its owning span is activated, and it is removed from the
 * context when that span's scope is closed.
 */
class MutableOpenTelemetryBaggage implements Baggage {

    private final Map<String, BaggageEntry> values = new ConcurrentHashMap<>();

    MutableOpenTelemetryBaggage() {
    }

    @Override
    public int size() {
        return values.size();
    }

    @Override
    public void forEach(BiConsumer<? super String, ? super BaggageEntry> consumer) {
        values.forEach(consumer);
    }

    @Override
    public Map<String, BaggageEntry> asMap() {
        return Map.copyOf(values);
    }

    @Override
    public String getEntryValue(String entryKey) {
        BaggageEntry entry = values.get(entryKey);
        return entry == null ? null : entry.getValue();
    }

    @Override
    public BaggageBuilder toBuilder() {
        BaggageBuilder builder = Baggage.builder();
        values.forEach((key, entry) -> builder.put(key, entry.getValue(), entry.getMetadata()));
        return builder;
    }

    /**
     * Make this baggage current by storing it in the current OpenTelemetry context.
     * <p>
     * This is used as part of activating the owning span so that the baggage travels with the span's context. The returned
     * {@link io.opentelemetry.context.Scope} restores the previous context (without this baggage) when closed.
     *
     * @return scope which restores the previous context when closed
     */
    @Override
    public Scope makeCurrent() {
        return Context.current().with(this).makeCurrent();
    }

    /**
     * Add or update a baggage entry.
     * <p>
     * This mutates only this baggage instance; it does not modify the OpenTelemetry {@link io.opentelemetry.context.Context}
     * and therefore never creates an additional context scope.
     *
     * @param key   baggage key
     * @param value baggage value
     */
    void baggage(String key, String value) {
        Objects.requireNonNull(key, "Baggage Key cannot be null");
        Objects.requireNonNull(value, "Baggage Value cannot be null");
        values.put(key, new MutableBaggageEntry(value));
    }

    private static final class MutableBaggageEntry implements BaggageEntry {
        private final String value;

        private MutableBaggageEntry(String value) {
            this.value = value;
        }

        @Override
        public String getValue() {
            return value;
        }

        @Override
        public BaggageEntryMetadata getMetadata() {
            return BaggageEntryMetadata.empty();
        }
    }
}
